func (r *QueryResolver) CarrierIntelMonitoringStatus(ctx context.Context) (*gqlmodel.CarrierIntelMonitoringStatus, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceCarrierIntelligence, permission.OpRead)
	if err != nil {
		return nil, err
	}
	tenant := resolvercore.TenantInfo(authCtx)

	provider, err := r.CarrierIntelProviderInfo(ctx, tenant)
	if err != nil {
		return nil, err
	}
	enrollmentCounts, err := r.CarrierIntelService.EnrollmentCounts(ctx, tenant)
	if err != nil {
		return nil, err
	}
	eventCounts, err := r.CarrierIntelService.EventCounts(ctx, tenant)
	if err != nil {
		return nil, err
	}
	feeds, err := r.CarrierIntelService.FeedStates(ctx, tenant)
	if err != nil {
		return nil, err
	}
	queue, err := r.CarrierIntelService.ReviewQueue(ctx, tenant, carrierIntelReviewQueueCountLimit)
	if err != nil {
		return nil, err
	}

	return &gqlmodel.CarrierIntelMonitoringStatus{
		Provider: provider,
		EnrollmentCounts: &gqlmodel.CarrierIntelEnrollmentCounts{
			Desired: enrollmentCounts.Desired,
			Active:  enrollmentCounts.Active,
			Pending: enrollmentCounts.Pending,
			Failed:  enrollmentCounts.Failed,
		},
		EventCounts:      eventCountsToModel(eventCounts),
		Feeds:            feeds,
		ReviewQueueCount: len(queue),
	}, nil
}

func (r *QueryResolver) CarrierMonitoringEnrollments(ctx context.Context, input gqlmodel.DataTableConnectionInput, filter *gqlmodel.CarrierMonitoringEnrollmentFilterInput) (*gqlmodel.CarrierMonitoringEnrollmentConnection, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceCarrierIntelligence, permission.OpRead)
	if err != nil {
		return nil, err
	}
	tenant := resolvercore.TenantInfo(authCtx)
	tableInput, err := gqlconnection.DataTableConnectionFromGraphQL(ctx, &input, tenant)
	if err != nil {
		return nil, err
	}
	control, err := r.CarrierIntelService.Control(ctx, tenant)
	if err != nil {
		return nil, err
	}
	request := &carrierintelports.ListEnrollmentConnectionRequest{
		Filter: tableInput.Filter,
		Cursor: tableInput.Cursor,
	}
	if provider, ok := control.PrimaryType(); ok {
		request.Provider = provider
	}
	if filter != nil {
		if filter.DesiredState != nil {
			request.DesiredState = *filter.DesiredState
		}
		request.VendorStates = filter.VendorStates
	}
	result, err := r.CarrierIntelService.ListEnrollments(ctx, request)
	if err != nil {
		return nil, err
	}
	return carrierMonitoringEnrollmentConnectionToModel(result)
}

