func (r *QueryResolver) CarrierIntelRawPayload(ctx context.Context, carrierID string, snapshotID string) (map[string]any, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceCarrierIntelligence, permission.OpExport)
	if err != nil {
		return nil, err
	}
	id, err := parseCarrierIntelID(carrierID, "carrierId", "Carrier")
	if err != nil {
		return nil, err
	}
	snapID, err := parseCarrierIntelID(snapshotID, "snapshotId", "Snapshot")
	if err != nil {
		return nil, err
	}
	payload, err := r.CarrierIntelService.RawPayload(ctx, resolvercore.TenantInfo(authCtx), snapID, carrierintelports.CarrierIntelSubjectRef{
		SubjectType: carrierintel.SubjectTypeCarrier,
		SubjectID:   id.String(),
	})
	if err != nil {
		return nil, err
	}
	var decoded any
	if err = sonic.UnmarshalString(payload, &decoded); err != nil {
		return nil, errortypes.NewBusinessError("The stored provider payload could not be read").WithInternal(err)
	}
	if object, ok := decoded.(map[string]any); ok {
		return object, nil
	}
	return map[string]any{"items": decoded}, nil
}

func (r *QueryResolver) CarrierIntelLookup(ctx context.Context, input gqlmodel.CarrierIntelLookupInput) (*gqlmodel.CarrierIntelProspectLookup, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceCarrierSourcing, permission.OpRead)
	if err != nil {
		return nil, err
	}
	request := &carrierintelservice.LookupProspectRequest{
		TenantInfo:   resolvercore.TenantInfo(authCtx),
		DOTNumber:    gqlscalar.StringValue(input.DOTNumber),
		DocketNumber: gqlscalar.StringValue(input.DocketNumber),
	}
	if input.Depth != nil {
		request.Depth = *input.Depth
	}
	result, existing, err := r.CarrierIntelService.LookupProspect(ctx, request)
	if err != nil {
		return nil, err
	}
	lookup := &gqlmodel.CarrierIntelProspectLookup{Snapshot: result.Snapshot}
	if id, found := existing[result.Snapshot.DOTNumber]; found {
		lookup.ExistingCarrierID = gqlid.IDPtr(id)
	}
	return lookup, nil
}

